# Client Class

class SqlClient(ConnectorClientBase):
    """Typed client for sql connector."""

    def __init__(
        self,
        connection_runtime_url: str,
        credential: TokenCredential | AzureKeyCredential,
        *,
        max_retry_attempts: int = 3,
        timeout: float = 30.0,
        use_exponential_backoff: bool = True,
        initial_retry_delay_seconds: float = 0.5,
        maximum_retry_delay_seconds: float = 120.0,
        retry_jitter_factor: float = 0.1,
        retry_unsafe_http_methods: bool = False,
        transport: Optional[HttpTransport] = None,
        **kwargs: Any,
    ):
        """
        Initialize a SqlClient.

        Args:
            connection_runtime_url: The connection runtime
                URL from Azure Portal.
            credential: Caller-owned Azure Core credential.
            max_retry_attempts: The maximum number of request attempts.
            timeout: The network timeout in seconds for each request.
                The value configures Azure Core retry and transport deadlines.
                Nonpositive values disable SDK and transport deadlines.
            use_exponential_backoff: Whether retries use exponential backoff.
            initial_retry_delay_seconds: The initial retry delay in seconds.
            maximum_retry_delay_seconds: The maximum retry delay in seconds.
            retry_jitter_factor: The jitter fraction applied to retry delays.
            retry_unsafe_http_methods: Whether unsafe HTTP methods may be
                retried.
            transport: Optional Azure Core HTTP transport closed by
                the client through its synchronous lifecycle.
            **kwargs: Optional Azure Core pipeline policy settings.
        """
        if not connection_runtime_url:
            raise ValueError("connection_runtime_url cannot be None or empty")

        if credential is None:
            raise ValueError("credential cannot be None")

        super().__init__(
            credential,
            max_retry_attempts=max_retry_attempts,
            timeout=timeout,
            use_exponential_backoff=use_exponential_backoff,
            initial_retry_delay_seconds=initial_retry_delay_seconds,
            maximum_retry_delay_seconds=maximum_retry_delay_seconds,
            retry_jitter_factor=retry_jitter_factor,
            retry_unsafe_http_methods=retry_unsafe_http_methods,
            transport=transport,
            **kwargs,
        )
        self._connection_runtime_url = connection_runtime_url.rstrip('/')

    @property
    def connector_name(self) -> str:
        return "sql"

    def _resolve_pagination_url(self, next_link: str, current_request_url: str) -> str:
        parsed_next_link = urlsplit(next_link)
        if not parsed_next_link.scheme or not parsed_next_link.netloc:
            if next_link.startswith("/"):
                return f"{self._connection_runtime_url}{next_link}"
            if next_link.startswith("?"):
                return f"{current_request_url.partition('?')[0]}{next_link}"
            return urljoin(current_request_url, next_link)

        parsed_connection = urlsplit(self._connection_runtime_url)
        next_link_hostname = parsed_next_link.hostname
        connection_hostname = parsed_connection.hostname
        if next_link_hostname is None or connection_hostname is None:
            raise ValueError("Pagination URLs must include a hostname.")

        next_link_port = parsed_next_link.port
        if next_link_port is None:
            next_link_port = 443 if parsed_next_link.scheme == "https" else 80
        connection_port = parsed_connection.port
        if connection_port is None:
            connection_port = 443 if parsed_connection.scheme == "https" else 80
        if next_link_hostname.lower() == connection_hostname.lower():
            if (
                parsed_next_link.scheme == parsed_connection.scheme
                and next_link_port == connection_port
            ):
                return next_link

            raise ValueError(
                "Pagination URL origin "
                f"'{parsed_next_link.scheme}://{next_link_hostname}:{next_link_port}' "
                "must use the connection runtime scheme and port."
            )

        suffix = parsed_next_link.path
        if parsed_next_link.query:
            suffix += f"?{parsed_next_link.query}"
        return f"{self._connection_runtime_url}{suffix}"

    def delete_item(
        self,
        server: str,
        database: str,
        table: str,
        id: str,
        *,
        timeout: Optional[float] = None,
        headers: Optional[Mapping[str, str]] = None,
        client_request_id: Optional[str] = None,
        response_hook: Optional[ConnectorResponseHook] = None,
    ) -> None:
        """
        Delete row

        This operation deletes a row from a table.
        """
        request_url = (
            f"{self._connection_runtime_url}"
            f"/v2"
            f"/datasets"
            f"/"
            f"{quote(quote(str(server), safe=''), safe='')}"
            f","
            f"{quote(quote(str(database), safe=''), safe='')}"
            f"/tables"
            f"/{quote(quote(str(table), safe=''), safe='')}"
            f"/items"
            f"/{quote(quote(str(id), safe=''), safe='')}"
        )

        response = self.http_client.send(
            "DELETE", request_url, body=None,
            timeout=timeout,
            headers=headers,
            client_request_id=client_request_id,
            response_hook=response_hook,
        )

        if response.status == 404:
            return None

        if not (200 <= response.status < 300):
            raise ConnectorException(
                "DELETE",
                request_url,
                response.status,
                response.text,
            )

